"use client";

import React, { useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { Mail, Lock, ArrowRight, Loader2, AlertCircle, CheckCircle2 } from "lucide-react";
import { AuthInputField } from "../common/AuthInputField";
import { authApi } from "@/lib/authApi";
import { useAuth } from "@/context/AuthContext";

interface LoginFormProps {
  onUnverifiedEmail?: (data: { email: string; otp: string }) => void;
}

export const LoginForm: React.FC<LoginFormProps> = ({ onUnverifiedEmail }) => {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { saveAuthSession, setLatestOtpInfo } = useAuth();

  const initialEmail = searchParams.get("email") || "";
  const registeredSuccess = searchParams.get("registered") === "true";
  const resetSuccess = searchParams.get("reset") === "true";

  const [email, setEmail] = useState(initialEmail);
  const [password, setPassword] = useState("");
  const [rememberMe, setRememberMe] = useState(true);
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [unverifiedPrompt, setUnverifiedPrompt] = useState<{
    email: string;
    otp: string;
  } | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(
    registeredSuccess
      ? "Account registered and verified successfully! Please log in."
      : resetSuccess
      ? "Password reset successfully! Please log in with your new password."
      : null
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMessage(null);
    setUnverifiedPrompt(null);

    if (!email.trim()) {
      setErrorMessage("Please enter your email address.");
      return;
    }
    if (!password) {
      setErrorMessage("Please enter your password.");
      return;
    }

    try {
      setLoading(true);
      const res = await authApi.login(email, password, rememberMe);

      // Check if user email is unverified (code 300 or message indicating email not verified)
      const isUnverified =
        (res as any).code === 300 ||
        res.message?.toLowerCase().includes("email not verified") ||
        res.message?.toLowerCase().includes("not verified") ||
        Boolean(
          res.data &&
            ("otp" in (res.data as any) ||
              (res.data as any).email_verified_status === false)
        );

      if (res.status && res.token && res.data) {
        setSuccessMessage("Login Successful! Navigating to Landing page...");
        saveAuthSession(res.token, res.data as any);
        setTimeout(() => {
          router.push("/");
        }, 800);
      } else if (isUnverified) {
        const unverifiedEmail =
          (res.data as any)?.email?.trim() || email.trim();
        const unverifiedOtp =
          (res.data as any)?.otp !== undefined && (res.data as any)?.otp !== null
            ? String((res.data as any).otp)
            : "";

        // Save OTP info in context
        setLatestOtpInfo({
          email: unverifiedEmail,
          otp: unverifiedOtp,
          type: "register",
        });

        if (onUnverifiedEmail) {
          onUnverifiedEmail({
            email: unverifiedEmail,
            otp: unverifiedOtp,
          });
        } else {
          setUnverifiedPrompt({
            email: unverifiedEmail,
            otp: unverifiedOtp,
          });
        }
      } else {
        const errorText =
          res.message ||
          (res.errors
            ? Object.values(res.errors).flat().join(". ")
            : "Invalid email or password. Please try again.");
        setErrorMessage(errorText);
      }
    } catch (err: any) {
      setErrorMessage(
        err?.message || "Connection failed. Please check your network and try again."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      {/* Success Notification Banner */}
      {successMessage && (
        <div className="p-3.5 rounded-xl bg-green-50 border border-green-200 text-green-800 text-xs font-semibold flex items-center gap-3">
          <CheckCircle2 className="w-5 h-5 flex-shrink-0 text-[#71AC16]" />
          <span>{successMessage}</span>
        </div>
      )}

      {/* Error Notification Banner */}
      {errorMessage && (
        <div className="p-3.5 rounded-xl bg-red-50 border border-red-200 text-red-700 text-xs font-semibold flex items-start gap-3">
          <AlertCircle className="w-5 h-5 flex-shrink-0 text-red-500 mt-0.5" />
          <div className="flex-1 leading-relaxed">{errorMessage}</div>
        </div>
      )}

      {/* Unverified Email Warning Banner */}
      {unverifiedPrompt && (
        <div className="p-4 rounded-xl bg-amber-50 border border-amber-300 text-amber-900 text-xs font-medium space-y-2.5">
          <div className="flex items-start gap-2.5">
            <AlertCircle className="w-5 h-5 flex-shrink-0 text-amber-600 mt-0.5" />
            <div>
              <p className="font-bold text-amber-950">Email Not Verified</p>
              <p className="text-amber-800 mt-0.5">
                Your email ({unverifiedPrompt.email}) has not been verified yet.
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={() => {
              if (onUnverifiedEmail) {
                onUnverifiedEmail(unverifiedPrompt);
              } else {
                router.push(
                  `/verify-otp?email=${encodeURIComponent(
                    unverifiedPrompt.email
                  )}&otp=${encodeURIComponent(unverifiedPrompt.otp)}`
                );
              }
            }}
            className="w-full py-2.5 px-4 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-lg transition-all shadow-sm flex items-center justify-center gap-1.5 cursor-pointer uppercase tracking-wider text-[11px]"
          >
            <span>Verify Email Now</span>
            <ArrowRight className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {/* Email Input */}
      <AuthInputField
        label="Email Address"
        type="email"
        name="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        placeholder="warrior@example.com"
        icon={<Mail className="w-4 h-4" />}
        required
        autoComplete="email"
      />

      {/* Password Input */}
      <AuthInputField
        label="Password"
        type="password"
        name="password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        placeholder="••••••••••••"
        icon={<Lock className="w-4 h-4" />}
        required
        autoComplete="current-password"
      />

      {/* Remember Me and Forgot Password */}
      <div className="flex items-center justify-between text-xs pt-1 select-none">
        <label className="flex items-center gap-2 cursor-pointer text-neutral-600 hover:text-neutral-900">
          <input
            type="checkbox"
            checked={rememberMe}
            onChange={(e) => setRememberMe(e.target.checked)}
            className="w-4 h-4 rounded border-neutral-300 text-[#71AC16] focus:ring-[#71AC16] accent-[#71AC16]"
          />
          <span className="font-medium">Remember me</span>
        </label>

        <Link
          href="/forgot-password"
          className="font-semibold text-neutral-600 hover:text-[#71AC16] transition-colors"
        >
          Forgot password?
        </Link>
      </div>

      {/* Submit Button */}
      <button
        type="submit"
        disabled={loading}
        className="w-full mt-2 py-3 px-6 rounded-full bg-[#71AC16] hover:bg-[#639912] active:scale-[0.98] text-white font-black uppercase tracking-wider text-sm transition-all shadow-md shadow-[#71AC16]/20 flex items-center justify-center gap-2 cursor-pointer disabled:opacity-60 disabled:cursor-not-allowed select-none"
      >
        {loading ? (
          <>
            <Loader2 className="w-5 h-5 animate-spin" />
            <span>Signing in...</span>
          </>
        ) : (
          <>
            <span>Log In</span>
            <ArrowRight className="w-4 h-4 stroke-[3]" />
          </>
        )}
      </button>

      {/* Quick Demo Pre-fill */}
      <div className="pt-2">
        <div className="flex items-center justify-between p-2.5 rounded-xl bg-neutral-50 border border-neutral-200 text-xs">
          <span className="text-neutral-500">Quick sample account?</span>
          <button
            type="button"
            onClick={() => {
              setEmail("user@gmail.com");
              setPassword("password");
            }}
            className="text-[#71AC16] hover:underline font-bold cursor-pointer"
          >
            Pre-fill credentials
          </button>
        </div>
      </div>
    </form>
  );
};
